import{_ as t,o as a,c as o,a5 as r}from"./chunks/framework.CXroN2RO.js";const d="/study/images/browser/audio-feedback-paths.svg",i="/study/images/browser/audio-feedback-echoes.svg",p=JSON.parse('{"title":"Web Audioのフィードバックディレイ — 反響の間隔と減衰","description":"","frontmatter":{"title":"Web Audioのフィードバックディレイ — 反響の間隔と減衰","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"browser","summary":"遅延させた出力を入力側に戻すと、短い音が一定間隔で繰り返される。反響の間隔と減衰を決める遅延時間と帰還ゲイン、Web Audioが循環を処理する仕組みを解説する。","aliases":["Web Audio API","フィードバックディレイ","feedback delay","帰還ゲイン","DelayNode","エコー","反響","フィードバックコムフィルター","インパルス応答","IIR"],"verification":"W3C Web Audio APIのDelayNodeと音声グラフのレンダリング、Julius O. SmithのPhysical Audio Signal Processingに照合（2026-11-06）"}},"headers":[],"relativePath":"browser/audio-feedback-delay.md","filePath":"browser/audio-feedback-delay.md"}'),s={name:"browser/audio-feedback-delay.md"};function l(c,e,n,h,g,u){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="web-audioのフィードバックディレイ-—-反響の間隔と減衰" tabindex="-1">Web Audioのフィードバックディレイ — 反響の間隔と減衰 <a class="header-anchor" href="#web-audioのフィードバックディレイ-—-反響の間隔と減衰" aria-label="Permalink to &quot;Web Audioのフィードバックディレイ — 反響の間隔と減衰&quot;">​</a></h1><p>短い効果音を一定の間隔で、少しずつ小さくしながら繰り返すには、遅延させた出力を入力側へ戻します。この経路を<strong>フィードバック</strong>（帰還）と呼びます。ループを1周する時間が反響の間隔になり、1周ごとのゲインが反響の弱まり方を決めます。<a href="https://www.dsprelated.com/freebooks/pasp/Feedback_Comb_Filters.html" target="_blank" rel="noreferrer">Julius O. Smithのフィードバック・コムフィルター</a></p><h2 id="出力を遅らせて同じ加算点に戻す" tabindex="-1">出力を遅らせて同じ加算点に戻す <a class="header-anchor" href="#出力を遅らせて同じ加算点に戻す" aria-label="Permalink to &quot;出力を遅らせて同じ加算点に戻す&quot;">​</a></h2><p>入力 <code>x[n]</code> と帰還信号を足し、出力 <code>y[n]</code> を作ります。出力の一部を <code>DelayNode</code> に送り、遅らせた信号を <code>GainNode</code> で <code>g</code> 倍して同じ加算点に戻します。理想モデルではループの遅延を <code>T</code> 秒とします。サンプルレートが <code>Fs</code> のとき、<code>T</code> が整数サンプルに相当するなら <code>D = T × Fs</code> です。<a href="https://www.w3.org/TR/webaudio/#DelayNode" target="_blank" rel="noreferrer">W3C Web Audio APIのDelayNode</a>、<a href="https://www.dsprelated.com/freebooks/pasp/Feedback_Comb_Filters.html" target="_blank" rel="noreferrer">Julius O. Smithの差分方程式</a></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>y[n] = x[n] + g × y[n − D]</span></span></code></pre></div><figure class="study-figure"><img src="'+d+'" alt="理想モデルの信号経路。入力と帰還信号を足して出力する。加算点の出力はDelayNodeでT秒遅れ、GainNodeでg倍され、同じ加算点へ戻る。" width="760" height="388" loading="lazy"><figcaption>遅延経路に入る信号には、元の音に加えて、すでに戻ってきた反響も含まれます。<a href="/study/images/browser/audio-feedback-paths.svg" target="_blank" rel="noopener noreferrer">フィードバック経路の図を拡大</a></figcaption></figure><p><code>y[n − D]</code> は過去の<strong>出力</strong>です。出力が一度戻ってくると、その信号も新しい出力に含まれ、次の周回へ入ります。以前のフィードフォワード型では過去の<strong>入力</strong> <code>x[n − D]</code> を足すため、1サンプルの入力から生じるのは直接音と遅延音の2点です。<a href="/study/browser/audio-comb-filter.html">Web Audioのコムフィルター</a></p><h2 id="反響は1周するたびに-g-倍になる" tabindex="-1">反響は1周するたびに g 倍になる <a class="header-anchor" href="#反響は1周するたびに-g-倍になる" aria-label="Permalink to &quot;反響は1周するたびに g 倍になる&quot;">​</a></h2><p>理想モデルの初期状態を無音とし、時刻0の1サンプルだけに振幅1を入力します。最初の出力は1です。その値が1周して <code>T</code> 秒後に <code>g</code>、もう1周して <code>2T</code> 秒後に <code>g²</code> になります。<code>k</code> 回目の反響は <code>kT</code> 秒後に現れ、振幅は <code>g</code> の <code>k</code> 乗です。<code>g &gt; 0</code> なら、1周前に対する振幅の変化は <code>20 × log10(g)</code> dB です。</p><table tabindex="0"><thead><tr><th style="text-align:right;">帰還ゲイン <code>g</code></th><th style="text-align:right;">直接音</th><th style="text-align:right;">1回目</th><th style="text-align:right;">2回目</th><th style="text-align:right;">3回目</th><th style="text-align:right;">1周ごとの変化</th></tr></thead><tbody><tr><td style="text-align:right;">0</td><td style="text-align:right;">1</td><td style="text-align:right;">0</td><td style="text-align:right;">0</td><td style="text-align:right;">0</td><td style="text-align:right;">反響なし</td></tr><tr><td style="text-align:right;">0.4</td><td style="text-align:right;">1</td><td style="text-align:right;">0.4</td><td style="text-align:right;">0.16</td><td style="text-align:right;">0.064</td><td style="text-align:right;">約 −7.96 dB</td></tr><tr><td style="text-align:right;">0.7</td><td style="text-align:right;">1</td><td style="text-align:right;">0.7</td><td style="text-align:right;">0.49</td><td style="text-align:right;">0.343</td><td style="text-align:right;">約 −3.10 dB</td></tr></tbody></table><figure class="study-figure"><img src="'+i+'" alt="理想モデルで遅延200ミリ秒のインパルス応答。直接音から5回目の反響までを表示。反響は200ミリ秒間隔で、帰還ゲイン0.7より0.4の方が振幅が速く小さくなる。" width="760" height="600" loading="lazy"><figcaption>理想モデルでループの遅延を200 msにそろえています。反響の位置は同じで、帰還ゲインが小さいほど早く減衰します。<a href="/study/images/browser/audio-feedback-echoes.svg" target="_blank" rel="noopener noreferrer">反響と減衰の図を拡大</a></figcaption></figure><p><code>|g| &lt; 1</code> なら反響の振幅は周回ごとにゼロへ近づきます。<code>g = 1</code> なら理想モデルでは同じ振幅で繰り返し、<code>g &gt; 1</code> では周回ごとに大きくなります。<code>|g| &lt; 1</code> でも、長い音を入れると過去の出力が現在の入力に重なってピークが大きくなることがあります。例えば一定の入力では、正の <code>g = 0.7</code> の出力は入力の約3.33倍に近づきます。実際に再生する音ではこの加算分も含めて振幅の余裕を取ります。<a href="https://www.dsprelated.com/freebooks/pasp/Feedback_Comb_Filters.html" target="_blank" rel="noreferrer">Julius O. Smithの安定条件</a>、<a href="/study/browser/audio-mixing-and-headroom.html">Web Audioのミキシングとヘッドルーム</a></p><h2 id="ブラウザが循環を処理する順序" tabindex="-1">ブラウザが循環を処理する順序 <a class="header-anchor" href="#ブラウザが循環を処理する順序" aria-label="Permalink to &quot;ブラウザが循環を処理する順序&quot;">​</a></h2><p>Web Audioは一定数のフレームをまとめて処理します。この単位を<strong>レンダークォンタム</strong>と呼びます。循環に入った <code>DelayNode</code> の遅延には1レンダークォンタム分の下限があります。現在のブロックをまだ書き込んでいなくても、以前に書き込んだ信号を先に読み出せるためです。仕様では遅延の読み出し側と書き込み側を分けてノードの実行順を決め、そこで解消できない循環に含まれるノードの出力を無音にします。<a href="https://www.w3.org/TR/webaudio/#DelayNode" target="_blank" rel="noreferrer">W3C Web Audio APIのDelayNode</a>、<a href="https://www.w3.org/TR/webaudio/#rendering-loop" target="_blank" rel="noreferrer">音声グラフのレンダリング</a></p><p>Chromium系ブラウザでこのサンプルを48,000 Hz、設定200 msで動かすと、反響間隔は9,728サンプル（約202.67 ms）でした。設定の200 msに当たる9,600サンプルとの差は128サンプルで、この実行での1レンダークォンタム分です。これはこの経路で観測した追加の時間です。上で説明した仕様の下限は、循環内の <code>DelayNode</code> に設定できる実効遅延の最小値を指します。</p><p>Chromiumの実装は、ノードの入力を取得する前に処理の開始時刻を記録します。循環して同じノードに戻ると再処理せず、バッファに残っている出力を使うので、今回の経路では1ブロックの差が生じたと考えられます。実践画面では、設定した時間と、そのブラウザの出力波形から測った実際の間隔を別々に表示します。<a href="https://chromium.googlesource.com/chromium/src/+/c3756773b1039618747068cee1080fd09f75f24e/third_party/blink/renderer/modules/webaudio/audio_handler.cc#292" target="_blank" rel="noreferrer">ChromiumのAudioHandler実装</a></p><h2 id="ゲームの効果音で間隔と音色を調整する" tabindex="-1">ゲームの効果音で間隔と音色を調整する <a class="header-anchor" href="#ゲームの効果音で間隔と音色を調整する" aria-label="Permalink to &quot;ゲームの効果音で間隔と音色を調整する&quot;">​</a></h2><p>坑道の奥で鳴った短い効果音に、一定間隔で弱まる反響を付けるときに使えます。遅延時間を短くすると反響が元の音と重なりやすくなります。1周の時間を <code>T</code>、帰還ゲインを一定の正の値としたモデルでは、1周して戻った波の位相がそろう周波数 <code>f = k / T</code>（<code>k = 0, 1, 2, …</code>）で振幅の山が並びます。この周期的な強調を持つ処理は<strong>フィードバック・コムフィルター</strong>とも呼ばれます。<a href="https://www.dsprelated.com/freebooks/pasp/Feedback_Comb_Filters.html" target="_blank" rel="noreferrer">Julius O. Smithのフィードバック・コムフィルター</a></p><p>部屋で聞く反響には、壁や床を通る複数の経路があり、反射する面によって周波数ごとの減衰も変わります。単一のループは、一定間隔の反響を作り、遅延時間と帰還ゲインの影響を個別に調べるためのモデルです。</p><h2 id="ブラウザで測って聴く" tabindex="-1">ブラウザで測って聴く <a class="header-anchor" href="#ブラウザで測って聴く" aria-label="Permalink to &quot;ブラウザで測って聴く&quot;">​</a></h2><p>実践サンプルは <code>OfflineAudioContext</code> で実際にノードを循環させ、直接音と5回目までの反響を測ります。設定時間を200 msから400 msに変え、波形から測った間隔を比べます。帰還ゲインを0.7から0.4に下げると、同じ回数でも反響の振幅が小さくなります。短い効果音でも間隔と減衰を聴き比べられます。<a href="/study/practice/browser/audio-feedback-observation.html">フィードバックディレイの実践</a>、<a href="https://www.w3.org/TR/webaudio/#OfflineAudioContext" target="_blank" rel="noreferrer">W3C Web Audio APIのOfflineAudioContext</a></p><p>反射が届く時刻と振幅を波形として用意し、その響きを別の音に加える方法もあります。<a href="/study/browser/audio-convolution-reverb.html">Web Audioの畳み込みリバーブ</a></p>',22)])])}const f=t(s,[["render",l]]);export{p as __pageData,f as default};
